Traditionally, SPDEs are perturbed by a space-time Gaussian white noise in dimension $d=1$, which is a zero-mean Gaussian process $\{B_t(\varphi);t> 0,\varphi \in L^2(\mathbb{R})\}$ with covariance:
\[
\mathbb{E}[B_t(\varphi) B_s(\psi)]=(t \wedge s) \langle \varphi,\psi \rangle_{L^2(\mathbb{R})}.
\]
In higher dimensions, Dalang introduced in \cite{dalang99}, a spatially-homogeneous (or colored) noise, as a zero-mean Gaussian process $\{W_t(\varphi);t\geq 0,\varphi \in \mathcal{S}(\mathbb{R})\}$ with covariance:
\begin{equation}
\label{def-cov-W}
\mathbb{E}[W_t(\varphi) W_s(\psi)]=(t \wedge s) \int_{\mathbb{R}^d} \int_{\mathbb{R}^d}\varphi(x)\psi(y) f(x-y)dxdy,
\end{equation}
where $\mathcal{S}(\mathbb{R}^d)$ is the set of all rapidly decreasing functions on $\mathbb{R}^d$, and $f:\mathbb{R}^d \to [0,\infty]$ is the Fourier transform of a tempered measure $\mu$. This noise can also be defined as:
\begin{equation}
\label{Gauss-color}
W_t(\varphi)=B_t(\varphi*\kappa) \quad \mbox{for all $t>0$ and $\varphi \in \mathcal{S}(\mathbb{R}^d)$},
\end{equation}
where the kernel $\kappa$ is chosen such that $k * \widetilde{k}=f$, and $\widetilde{k}(x):=k(-x)$ for all $x \in \mathbb{R}^d$.

Let $G$ be the fundamental solution of the wave equation in dimension $d=1$, given by:
\begin{equation}
\label{def-G}
G_t(x)=\frac{1}{2}1_{\{|x|<t\}} \quad \mbox{for all $t>0$ and $x \in \mathbb{R}$.}
\end{equation}

By Lemma 5.5 of \cite{BJ25}, the process $\{u(t,x)\}_{x\in \mathbb{R}}$ is strictly stationary, for any $t>0$.
Moreover, by Theorem 5.6 of \cite{BJ25}, if for some $p\geq 2$, we have
\begin{equation}
\label{def-mp}
m_p:=\int_{\bR_0}|z|^p \nu(dz)<\infty,
\end{equation}
and
\begin{equation}
\label{def-Mp}
\cM_p(t):=\int_0^t \int_{\mathbb{R}} \big|(G_{t-s}*\kappa)(x)\big|^p dx ds<\infty \quad \mbox{for all} \quad t>0,
\end{equation}
then
\begin{equation}
\label{mom-u}
K_p(T):=\sup_{(t,x)\in [0,T] \times \mathbb{R}}\|u(t,x)\|_p<\infty \quad \mbox{for all} \quad T>0,
\end{equation}
where $\|\cdot\|_p$ denotes the norm in $L^p(\Omega)$. The goal of the present paper is to complement this analysis by showing that the {\em spatial average} of the (centered) solution:
\[
F_R(t)=\int_{-R}^{R}\big(u(t,x)-1 \big)dx.
\]
has asymptotic Gaussian fluctuations when $R \to \infty$, with a precise rate of convergence which depends on the noise. We denote $\sigma_R^2(t)={\rm Var}(F_R(t))$.

\begin{remark}
\label{rem-M}
{\rm Suppose that Assumption B holds. Applying Young's inequality if $\kappa \in L^1(\mathbb{R})$, and Theorem \ref{HLS} if $\kappa=R_{1,\alpha/2}$, we see that:
\[
\|G_t* \kappa\|_{L^p(\mathbb{R})} \leq
\left\{
\begin{array}{ll} 
\|\kappa\|_{L^1(\mathbb{R})} \|G_t\|_{L^p(\mathbb{R})} & \mbox{if $\kappa \in L^1(\mathbb{R})$ and $p\geq 1$} \\
A_{1,\alpha,p}\|G_t\|_{L^q(\mathbb{R})} & \mbox{if $\kappa=R_{1,\alpha/2}$, $\alpha \in (0,1)$, $p>\frac{2}{2-\alpha}$ and $\frac{1}{q}=\frac{1}{p}+\frac{\alpha}{2}$}
\end{array} \right.
\]
Since $\|G_t\|_{L^p(\mathbb{R})}^p=2^{1-p}t$ for any $p>0$, we infer that condition \eqref{def-Mp} holds for any $p\geq 2$. Therefore, \eqref{mom-u} holds for any $p \geq 2$ such that $m_p<\infty$.
}
\end{remark}

We recall the following definitions. Let $X$ and $Y$ be random variables defined on the same probability space.
The {\em $1$-Wasserstein distance} between $X$ and $Y$ is:
\[
d_{W}(X,Y)=\sup_{{\rm Lip}(h) \leq 1} \big|\mathbb{E}[h(X)]-\mathbb{E}[h(Y)]\big|, \quad
\mbox{where} \quad
{\rm Lip}(h):=\sup_{x \not=y}\frac{|h(x)-h(y)|}{|x-y|}.
\]
The {\em Fortet-Mourier distance} between $X$ and $Y$ is:
\[
d_{FM}(X,Y)=\sup_{\|h\|_{\infty}+{\rm Lip}(h) \leq 1} \big|\mathbb{E}[h(X)]-\mathbb{E}[h(Y)]\big|,
\]
The {\em Kolmogorov distance} between $X$ and $Y$ is:
\[
d_{K}(X,Y)=\sup_{x \in \mathbb{E}} \big|P(X \leq x)-P(Y \leq x)\big|.
\]

We are now ready to state the main results of this article.

\begin{theorem}[Hardy-Littlewood-Sobolov inequality]
\label{HLS}
For any $\alpha \in (0,d)$ and $p>\frac{d}{d-\alpha}$, 
\[
\| \varphi *R_{d,\alpha}\|_{L^p(\bR^d)} \leq A_{d.\alpha,p}\|\varphi\|_{L^{q}(\bR^d)} \quad \mbox{for any $\varphi \in L^q(\bR^d)$},
\]
where $A_{d,\alpha,p}>0$ is a constant depending on $(d,\alpha,p)$, and $q$ is defined by:
\[
\frac{1}{q}=\frac{1}{p}+\frac{\alpha}{d}.
\]
(Condition $p>\frac{d}{d-\alpha}$ is equivalent to $q>1$.)
\end{theorem}

