 The disjoint union of a consistently forward and a consistently backward oriented ray is ubiquitous if and only if it is ubiquitous restricted to the class of one-ended digraphs.
\end{theorem}

\begin{proof}[Proof of Theorem~\ref{thm:main:intro:ReductionToOneEnd:doubleRays}.]
 Let us assume that Problem~\ref{prob:ubiquity:doubleRays} holds for the class of one-ended digraphs and let $D$ be a digraphs and $(\cR_n)_{n\in\N}$ be a valid sequence in~~$D$.
 By Theorem~\ref{thm:ubiquity:doubleRays}, we may assume that $(\cR_n)_{n\in\N}$ concentrates in finitely many ends.
 Then there is a valid sequence $(\cQ_n)_{n\in\N}$ induced by $(\cR_n)_{n\in\N}$ such that all tails from all elements of $\bigcup_{n\in\N}\cQ_n$ are equivalent.
 By Lemma~\ref{lem:reduction:doubleRays:oneEnd}, there exists a one-ended subdigraph $D'$ of~$D$ and a valid sequence $(\cP_n)_{n\in\N}$ in~$D'$ induced by $(\cQ_n)_{n\in\N}$.
 Thus, there are infinitely many pairwise disjoint double rays in~$D'$ and hence in~$D$.
\end{proof}

\begin{problem}\cite{GKR2024}*{Problem 1.3}\label{prob:ubiquity:doubleRays}
    Is the consistently oriented double ray ubiquitous?
\end{problem}

\begin{theorem}\label{thm:main:intro:ReductionToOneEnd:doubleRays}
    The consistently oriented double ray is ubiquitous if and only if it is ubiquitous restricted to the class of one-ended digraphs.
\end{theorem}

\begin{thm}\label{thm:ubiquity:doubleRays}
    Let $D$ be a digraph.
    If there is a valid sequence $(\cR_n)_{n\in\N}$ that does not concentrate in finitely many ends, then $D$ contains infinitely many pairwise disjoint double rays.
\end{thm}

