\begin{abstract}
A classification is given of finite $k$-set-homogeneous graphs for $k\geqslant 2$, leading to a striking result that each finite $k$-set-homogeneous graph is $k$-homogeneous. It shows that $3$-set-homogeneous graphs are rare, consisting of the following graphs and their complements: $\C_5$, $\K_n\square\K_n$, $n\K_m$, the Schl\"{a}fli graph of order 27, the Higman-Sims graph, the MaLaughlin graph, {affine polar graphs, and elliptic orthogonal graphs}. As an ingredient for the proof, it is shown that all orbitals in a primitive permutation group of rank $4$ are self-paired, except for $\PSU_3(3)$ acting on 36 points.
\bigskip

The main purpose of this paper is to solve Problem~B by proving that every $k$-set-homogeneous graph is $k$-homogeneous for $k\geqslant 2$, { so that $k$-set-homogeneous graphs are explicitly classified, as described in the previous paragraph.}
To state {our main theorem}, we fix some graph notation. Let $m$ and $n$ be positive integers. We denote the complete graph with $n$ vertices by $\K_n$, the cycle with $n$ vertices by $\C_n$, the complete multipartite graph with $n$ parts of
size $m$ by $\K_{n[m]}$, and its complement (the disjoint union of $n$ copies of $\K_m$) by $n\K_m$. Let $\K_n\square\K_n$ and $\K_n\times\K_n$ be the Cartesian product and direct product of two $\K_n$'s, respectively. For a graph $\Ga$, we denote by $\ov\Ga$ the {\it complement} of $\Ga$. Note that $\overline{\K_n\square\K_n}=\K_n\times\K_n$.

{\noindent{\bf Remark on Theorem~\ref{th-main}.}\ For $k\geq2$, all $k$-homogeneous graphs have already been classified in the literature, { as mentioned above}, and so all graphs in Theorem~\ref{th-main}~(1)--(4) are known.}\medskip

\begin{theorem}\label{th:2sethomo}
Let $\Ga=(V,E)$ be a finite $(G,2)$-set-homogeneous graph, where $G\leq\Aut(\Ga)$.
Then one of the following holds:
\begin{itemize}
\item[{\rm(1)}] $\Ga\cong\K_n$ or $n\K_1$, and $G$ is a $2$-homogeneous permutation group on $V$.

\begin{theorem}\label{th:3sethomo}
Let $\Ga=(V,E)$ be a finite $3$-set-homogeneous graph. Then, up to complement, $\Ga$ is isomorphic either to one of the graphs: $\C_5$, $\K_n$, $\K_{m[b]}$, $\K_n\square\K_n$, or to one of the following graphs:
\begin{itemize}
\item[{\rm(1)}] the affine polar graph $\mathrm{VO}_{2m}^{\epsilon}(2)$ with $m\geq 1$ and $\epsilon \in \{+,-\}$;

\begin{theorem}[\cite{Liebeck-affine}]\label{subdegree}
Let $X$ be a finite primitive affine permutation group of rank $3$ and of degree $p^d$, with socle $V$, where $V\cong\mz_p^d$ for some prime $p$, and let $X_0$ be the stabiliser of the zero vector in $V$. Then $X_0$ belongs to one of the following classes $($and, conversely, each of the possibilities listed below does give rise to a rank $3$ affine group$)$.
\begin{itemize}
\item[\rm (A)] Infinite classes. These are
\begin{itemize}
\item[\rm (1)] $X_0\leq \mathrm{\Gamma L}_1(p^d)$: all possibilities for $X_0$ are determined in~\cite[\textsection{3}]{Foulser-Kallaher-solvable-rank-3};
\item[\rm (2)] $X_0$ imprimitive: $X_0$ stabilises a pair $\{V_1,V_2 \}$ of subspaces of $V$ where $V=V_1 \oplus V_2$ and $\dim(V_1)=\dim(V_2)$; moreover, $(X_0)_{V_i}$ is transitive on $V_i\setminus 0$ for $i=1$, $2$ (and hence $ X_0$ is determined by Hering's Theorem~\cite{Hering});
\item[\rm (3)] tensor product case: for some $a$, $q$ with $q^a= p^d$, consider $V$ as a vector space $\GF(q)^a$ of dimension $a$ over $\GF(q)$; then $X_0$ stabilises a decomposition of $\GF(q)^a$ as a tensor product $V_1 \otimes V_2$ where $\dim_{\GF(q)}(V_1)=2$; moreover, $(X_0)^{V_2}\vartriangleright \SL(V_2)$, or $(X_0)^{V_2}=\A_7<\SL_4(2)$ $($and $p=q=2$, $d=a=8)$, or $\dim_{\GF(q)}(V_2)\leq 3$;
\item[\rm (4)] $X_0\vartriangleright \SL_a(q) $ and $p^d=q^{2a}$;
\item[\rm (5)] $X_0\vartriangleright \SL_2(q) $ and $p^d=q^{6}$;
\item[\rm (6)] $X_0\vartriangleright \mathrm{SU}_a(q) $ and $p^d=q^{2a}$;
\item[\rm (7)] $X_0\vartriangleright \Omega^{\pm}_{2a}(q)$ $($and if $q$ is odd, $X_0$ contains an automorphism interchanging the two orbits of $\Omega^{\pm}_{2a}(q)$ on nonsingular $1$-spaces$)$;
\item[\rm (8)] $X_0\vartriangleright \SL_5(q) $ and $p^d=q^{10}$ $($from the action of $\SL_5(q)$ on $\bigwedge^2( \GF(q) ^5)$, the exterior square of $\GF(q)^5)$;

\begin{lemma}\label{lem:class:b-c}
If $G$ satisfies Theorem~{\rm\ref{subdegree}} {\rm(B)--(C)}, then one of the following holds:
\begin{enumerate} [\rm (1)]
\item $\Ga\cong \mathrm{VO}^{-}_6(2)$ or $\overline{\mathrm{VO}^{-}_6(2)}$, arising from the case where $p^d=2^6$ and $G_0\leq \N_{\GL_6(2)}(3^{1+2})$ in {\rm(B)};
\item $\Ga\cong \K_9\square\K_9$ or $\K_9\times\K_9$, arising from the case where $p^d=3^4$ and $G_0\leq \N_{\GL_4(3)}(2^{1+4}) $ in {\rm(B)};
\item $\Ga\cong \mathrm{VO}^{+}_8(2)$ or $\overline{\mathrm{VO}^{+}_8(2)}$, arising from the case where $p^d=2^8$ and $\soc(G_0/\Z(G_0))=\A_9<\mathrm{P\Omega}^{+}_8(2)$ in {\rm(C)}.
\end{enumerate}
\end{lemma}

\begin{proof} Assume that $G$ is of type {\rm(A1)}. Then $G\leq \mathrm{A\Gamma L}_1(p^d)$. Let $\{\alpha, \beta\}$ be an edge of $\Ga$.
Then $|V(\Ga)|=p^d$ and $G_{\alpha\beta}\leq \ZZ_d$. Furthermore, $G_{\a\b}$ is semiregular on $V(\Ga) \setminus \{\alpha, \beta\}$.
From Lemma~\ref{lm:Gab10orbits} it follows that $G_{\alpha\beta}$ has at most $12$ orbits on $V(\Ga) \setminus \{\alpha, \beta\}$.
Therefore, $G_{\alpha\beta}$ has one orbit of length at least $(|V(\Ga)|-2)/12$.
It follows that $|G_{\alpha\beta}|\geq (|V(\Ga)|-2)/12$, which means
\[ p^d-2 \leq 12d.\]
This implies that
\[
p^d\in\{2^i (1\leq i\leq6), 3^j (1\leq j\leq 3), 5^k, 7^k, 11^k (1\leq k\leq 2), 13\}.
\]
Since $\Ga$ has girth $3$ and diameter $2$ by Hypothesis~\ref{hyp}, it follows that $|V(\Ga)|=p^d\geq7$. For all of the remaining possible values of $p^d$, we make use of Magma~\cite{BCP} to construct all primitive rank $3$ subgroups $G$ of $\mathrm{A\Gamma L}_1(p^d)$, and then for each rank $3$ graph arising from $G$, we can further check if $|\Om_i(\Ga)|$ divides $|G|$ for $i=1,2,3,4$, where $\Om_i(\Ga)$ is given in Lemma~\ref{lm:Gaorder}. We find that the only possibility is $p^d=3^2$, and $\Ga\cong \mathrm{Paley}(9)\cong\K_3\square\K_3$. \hfill\qed
\end{proof}

selected.post_theorem_intro_text:
{\noindent{\bf Remark on Theorem~\ref{th-main}.}\ For $k\geq2$, all $k$-homogeneous graphs have already been classified in the literature, { as mentioned above}, and so all graphs in Theorem~\ref{th-main}~(1)--(4) are known.}\medskip

By definition, a $k$-homogeneous graph is $k$-set-homogeneous.
The converse of this statement is clearly true for $k=1$.
{In the case where $k\ge4$,}
{Devillers~\cite{Devillers-2002paper}} proved that every finite $5$-set-homogeneous graph is set-homogeneous, and that a $4$-set-homogeneous graph is either homogeneous or one of the Schl\"{a}fli graph on $27$ vertices and its complement, which are $4$-homogeneous (see, for example, \cite[Proposition~3.2.1]{Devillers}).
{So, to prove Theorem~\ref{th-main}, it suffices to show that every $k$-set-homogeneous graph is also $k$-homogeneous for $k=2$ and 3.}

Before stating the results, we introduce some families of graphs.

\begin{definition}\label{Def-graph-families}
{\rm \begin{itemize}
\item[\rm (1)]  Let ${\rm GF}(q)$ be a field of order a prime power $q$ such that $q\equiv 1\ (\mod 4)$, and let $\o$ be a fixed primitive { element} of ${\rm GF}(q)$.
Let $S=\{\o^2, \o^4, \ldots, \o^{q-3}, \o^{q-1}\}$. The {\it Paley graph} of order $q$, denoted by {\rm Paley}$(q)$, is the graph with vertex set ${\rm GF}(q)$ { where} two vertices $x,y$ are adjacent if and only if $x-y\in S$.

\item[\rm (2)]  For a positive integer $n$, the {\it Hamming graph}, denoted by $\mathrm{H}(2,n)$, is the graph with vertex set {$\{(i, j) \mid 1\leqslant i, j\leqslant n\}$}, and for every vertex $(i, j)$, its neighbour set is
\[
\{ (i,j')\mid j' \in \{1,2,\dots,n \}\setminus \{j\}\} \cup \{ (i',j)\mid i' \in \{1,2,\dots,n \}\setminus \{i\}\}.
\]
Note that $\mathrm{H}(2,n)$ is just the Cartesian product $\K_n\square\K_n$.

\item[\rm (3)]  For $\epsilon \in \{+,-\}$, a positive integer $m$ and a prime power $q$, the {\it affine polar graph}, denoted by $\mathrm{VO}_{2m}^{\epsilon}(q)$, is a graph with vertex set $\GF(q)^{2m}$ equipped with a nondegenerate quadratic form $Q$ of type $\epsilon$, and two vertices $\alpha$ and $\alpha'$ being adjacent if and only if $Q(\alpha-\alpha')=0$ (see \cite[\textsection{3.3.1}]{BrouwerSRG}). Since a nondegenerate $2$-dimensional orthogonal vector space of type $-$ contains no singular vector, it follows that $\mathrm{VO}_{2}^{-}(q)\cong q^2\K_1$. As remarked in~\cite[\textsection{3.3.1}]{BrouwerSRG}, we see that $\mathrm{VO}_{2}^{+}(q)\cong \K_q\square\K_q=\mathrm{H}(2,q)$.

\item[\rm (4)] For a prime power $q$, the {\it elliptic orthogonal graph}, denoted by $\mathrm{\Gamma}(\mathrm{O}^{-}_6(q))$ is a graph with vertex set consisting of  all singular $1$-subspaces of the orthogonal space on {$\GF(q)^{6}$ of type $-$},
    and two vertices $\alpha=\langle w \rangle$ and $\alpha'=\langle w' \rangle$ being adjacent if and only if $w\perp w'$ (see \cite[\textsection{2.6.3}]{BrouwerSRG}). The Schl\"{a}fli graph is the complement of the elliptic orthogonal graph $\mathrm{\Gamma}(\mathrm{O}^{-}_6(2))$ (see \cite[Table~11.8]{BrouwerSRG}).
\end{itemize}}
\end{definition}

We recall that a transitive permutation group $G$ on a set $\Ome$ is {\it $2$-homogeneous} if
all $2$-subsets of $\Ome$ are equivalent under $G$.
In the next theorem, a classification of finite $2$-set-homogeneous graphs is given.

\begin{theorem}\label{th:2sethomo}
Let $\Ga=(V,E)$ be a finite  $(G,2)$-set-homogeneous graph, where $G\leqslant\Aut(\Ga)$.
Then one of the following holds:
\begin{itemize}
\item[{\rm(1)}] $\Ga\cong\K_n$ or $n\K_1$, and $G$ is a $2$-homogeneous permutation group on $V$.

\item[{\rm(2)}] $\Ga\cong\K_{m[b]}$ or $m\K_b$, and  $G\leqslant X\wr Y$,
where $X,Y$ are $2$-homogeneous permutation groups of degree $b,m$, respectively.

\item[{\rm(3)}] $G$ is primitive of rank $3$, and $\Ga$ is $(G,2)$-homogeneous.

\item[{\rm(4)}] $G\cong\PSU_3(3)$ with vertex stabiliser $\PSL_3(2)$, $\Ga$ is of order $36$ and
valency $14$ or $21$, but $\Aut(\Ga)=\PSU_3(3).2$ is $2$-homogeneous on $\Ga$.

\item[(5)] $\Ga$ is a Paley graph of order $p^r$, where $p\equiv5 \pmod{8}$ and $r$ is odd, and
