\begin{document}
\maketitle
\begin{abstract}
In this paper, we establish global strong solutions for arbitrarily large initial data to the multi-dimensional compressible Navier-Stokes–Korteweg system, also referred to as the quantum Navier–Stokes equations, originally derived by Dunn and Serrin [Arch. Ration. Mech. Anal. 88(2):95–133, 1985]. Specifically, we prove the existence of global strong solutions for arbitrarily large initial data in the case $N=2$ when $\gamma \ge 1$, and $N=3$ with $1 \le \gamma < 8/3$ for the associated Cauchy problem. By employing techniques from Littlewood–Paley theory, range truncation analysis, refined Nash-Moser and De Giorgi iteration methods, we derive positive upper and lower bounds for the density. As a consequence, we are able to treat the whole-space case with strictly positive far-field density. To the best of our knowledge, this is the first result that establishes global strong solutions for physically relevant compressible Navier–Stokes equations in the whole space, without imposing any symmetry or special geometric assumptions on the initial data.
\end{abstract}
\bigskip
\noindent \textbf{Keywords:} compressible Navier-Stokes-Korteweg system; quantum Navier-Stokes system; global large strong solutions; Nash-Moser iteration; De Giorgi iteration; Cauchy problem.

In the first phase, we work within the framework of Besov spaces, utilizing maximal regularity estimates for parabolic equations to secure the upper bound. The second and most crucial step is establishing the density lower bound. Although Haspot \cite{Haspot 1} investigated the isothermal NSK system, his approach failed to yield a lower bound for the density. Our strategy draws inspiration from a key inequality introduced by the first author in \cite{Huang-Meng-Zhang}. However, the technique in \cite{Huang-Meng-Zhang} cannot be directly applied to the whole space problem with non-vacuum far-field conditions. To overcome this obstacle, we have developed a novel truncated De Giorgi iteration method.

\begin{proof}
By H\"{o}lder's inequality, Sobolev embedding and \eqref{eq:19}, we have
\begin{equation}\label{the initial estimate for Psi}
\begin{aligned}
 \Psi(r(p+2)) &= \int^{T}_{0}\int_{\mathbb{R}^{3}}\rho|v|^{\frac{5}{3}(p+2)}\,dx\,dt \\
 &\leq \int^{T}_{0}\left( \int \rho^{\frac{3}{2}}|v|^{p+2}\,dx \right)^{\frac{2}{3}} \left( \int|v|^{3(p+2)}\,dx \right)^{\frac{1}{3}}\,dt \\
 &\leq \|\rho\|_{L_{T}^{\infty}L^{\infty}}^{\frac{1}{3}} \sup_{0 \le t \le T}\left( \int \rho|v|^{p+2}\,dx \right)^{\frac{2}{3}} \int^{T}_{0} \left\| |v|^{\frac{p+2}{2}} \right\|_{L^{6}}^{2}\,dt \\
 &\leq C \sup_{0 \le t \le T}\left( \int \rho|v|^{p+2}\,dx\right)^{\frac{2}{3}} \|\rho^{-1}\|_{L_{T}^{\infty}L^{\infty}} \\
 &\quad \times \left( \int^{T}_{0}\int \rho \left| \nabla|v|^{\frac{p+2}{2}} \right|^{2}\,dx\,dt + \int^{T}_{0}\int \rho|v|^{p+2}\,dx\,dt \right) \\
 &\le CV_{T} \left( \sup_{0 \le t \le T}\int \rho|v|^{p+2}\,dx + \int^{T}_{0}\int \rho \left| \nabla|v|^{\frac{p+2}{2}} \right|^{2}\,dx\,dt \right)^{r}.
\end{aligned}
\end{equation}
To estimate the right hand side, multiplying $\eqref{parabolic_system}_2$ by $|v|^{p}v$ and integrating by parts yields
\begin{equation}
 \frac{1}{p+2} \frac{d}{dt}\int \rho|v|^{p+2}dx+p\int \rho|v|^{p}\left| \nabla \left|v \right| \right| ^{2}dx+\int \rho|v|^{p}|\nabla v|^{2}dx=\int P(\rho)\nabla\cdot\left(\left| v \right| ^{p}v\right)dx.
\end{equation}
By Young's inequality and \eqref{eq:19}, we have
\begin{equation}
 \begin{aligned}
 \int P(\rho)\nabla \cdot\left(\left| v \right| ^{p}v\right)dx
=& \int \rho^{\gamma}(\left| v \right| ^{p}\nabla \cdot v+ v\cdot { \nabla \left( \left| v \right| ^{p} \right) } )dx\\
\leq& \int\rho^{\gamma}\left| v \right| ^{p} \left| \nabla v \right|dx + p\int \rho^{\gamma}|v|^{p}\left| \nabla \left| v \right| \right|dx \\
\leq & \frac{1}{2} \int \rho|v|^{p}|\nabla v|^{2}dx+ \frac{p}{2}\int \rho|v|^{p}|\nabla \left| v \right| |^{2} dx+ C(p+1)\int \rho^{2\gamma-1}|v|^{p}dx\\
 \leq& \frac{1}{2}\int \rho |v|^{p}\left| \nabla v \right| ^{2}dx+ \frac{p}{2}\int \rho|v|^{p}|\nabla \left| v \right| |^{2}dx + C(p+1)\left\lVert \rho \right\rVert _{L^{\infty}}^{2(\gamma-1)}\int \rho|v|^{p}dx\\ 
 \leq& \frac{1}{2}\int \rho |v|^{p}\left| \nabla v \right| ^{2}dx+ \frac{p}{2}\int \rho|v|^{p}|\nabla \left| v \right| |^{2}dx\\
 &+ C(p+1)\sup_{0 \le t \le T}\left( \int \rho|v|^{2}dx \right)^{\frac{2}{p}}\left( \int \rho|v|^{p+2} dx\right)^{1- \frac{2}{p}}.
\end{aligned}
\end{equation}
Combining \eqref{v energy}, we have
\begin{equation}
 \frac{1}{p+2}\frac{d}{dt}\int \rho |v|^{p+2}dx + \frac{1}{2}\int \rho |v|^p |\nabla v|^2dx + \frac{p}{2}\int \rho |v|^p |\nabla |v||^2dx \leq C(p+1)\left( \int \rho |v|^{p+2} dx \right)^{1-\frac{2}{p}}.
\end{equation}
Integrating over $t\in[0,T]$, we obtain
\begin{equation}
 \begin{aligned}
&\sup_{0 \le t \le T}\frac{1}{p+2}\int{\rho}|v|^{p+2}dx+ \frac{1}{2}\int_{0}^{T}\int \rho |v|^p |\nabla v|^2dxdt + \frac{p}{2}\int_{0}^{T}\int \rho |v|^p |\nabla |v||^2dxdt \\
\leq &C(p+1)\int^{T}_{0}\left( \int \rho |v|^{p+2} dx \right)^{1-\frac{2}{p}}dt+\frac{2}{p+2}\int \rho_{0}|v_{0}|^{p+2}\\
\leq& C(p+1){T^{*}}^{\frac{2}{p}}\left( \int^{T}_{0}\int \rho|v|^{p+2}dxdt \right)^{1- \frac{2}{p}}+ \frac{2}{p+2}\int \rho_{0}|v_{0}|^{p+2}.
\end{aligned}
\end{equation}
Substituting this into the RHS of \eqref{the initial estimate for Psi}, we get
\begin{equation}
 \begin{aligned}
\Psi(r(p+2))&\leq C{V}_{T} \left( C(p+2)^2 \left( \int^{T}_{0}\int \rho |v|^{p+2} dxdt \right)^{\frac{p-2}{p}} + C \int \rho_0 |v_0|^{p+2} dx \right) ^{r }\\
&\leq C{V}_{T} (p+2)^{2r } \left( \int^{T}_{0}\int \rho |v|^{p+2} dxdt \right)^{r } + C{V}_{T} (p+2)^{2r } + C{V}_{T} \left( \int \rho_0 |v_0|^{p+2} dx \right)^{r }.
\end{aligned}
\end{equation}
Denoting the constant in the RHS as $C_{3}\geq1$, and noting that
\begin{equation}
 \left\| \rho_0^{\frac{1}{p+2}} v_0 \right\|_{L^{p+2}} \leq \left\| \rho_0^{\frac{1}{2}} v_0 \right\|_{L^2}^{\frac{p}{p+2}} \|v_0\|_{L^\infty}^{\frac{2}{p+2}} \leq \left\| \rho_0^{\frac{1}{2}} v_0 \right\|_{L^2} + \|v_0\|_{L^\infty},
\end{equation}
the proof is complete.
\end{proof}
The following proposition plays a pivotal role in deriving the positive lower bound for the density, as it establishes a crucial link between the density and the effective velocity.
\begin{proposition}
There exists a constant $c_{v}\geq 1$ depending on $T^{*}$, $q$, $\gamma$, $E_{0}$, $\left\lVert \rho_{0}^{\frac{1}{q+2}}v_{0} \right\rVert_{L^{q+2}}$, and $\left\lVert \rho_{0} \right\rVert_{L^{\infty}}$ such that
\begin{equation}\label{eq:v_L_infty_est}
 \left\lVert v \right\rVert _{L_{T}^{\infty}\left(L^{\infty}\left(\mathbb{R}^3\right)\right)}\leq c_{v}(\log V_{T} )^{\frac{1}{2}}.
\end{equation}
\end{proposition}

