ref_dict.pro:metric on tube:
\begin{pro}
\label{pro:metric on tube}
There exists a constant $c>0$ such that the following holds. Let $V$ be a solid torus. Suppose that the boundary $\partial V$ is equipped with a flat metric of area $A$. Assume that the length of the flat geodesic representative on $\partial V$ of the meridian $\mu\subset\partial V$ is $\ell>2\pi$. Then there exists a smooth Riemannian metric $(V,g)$ with the following properties.
\begin{itemize}
    \item{The metric $g$ is a hyperbolic cusp metric in a collar of $\partial V$, the boundary $\partial V$ is a horospherical section of the cusp, and the restriction of $g$ to the boundary agrees with the prescribed flat metric on $\partial V$.}
    \item{Denote by $S_g$ the scalar curvature of the metric $g$. We have
    \[
    \int_V{\left(\frac{|S_g|}{6}\right)^{3/2}{\rm dvol}_g}\le\frac{A}{2}\left(1-\frac{\pi^2}{\ell^2}\right)\left(1+c\frac{\pi^4}{\ell^4}\right).
    \]
    }
\end{itemize}    
\end{pro}

ref_dict.lem:functiondrill:
\begin{lem}
\label{lem:functiondrill}
There exists a constant $c>0$ such that the following holds. For every $R>0$ there exist functions $a_{\rm drill},b_{\rm drill}:\mb{R}\to\mb{R}$ such that 
\begin{enumerate}
    \item{$a_{\rm drill},b_{\rm drill}>0$.}
    \item{$a_{\rm drill}(r)=\sinh(r),b_{\rm drill}(r)=\cosh(r)$ on $(2R/3,\infty)$.}
    \item{$a_{\rm drill}(r)=\sinh(R)e^r,\cosh(R)b_{\rm drill}(r)=e^r$ on $(-\infty,R/3)$.}
    \item{On $[R/3,2R/3]$ we have
    \[
    \left|\frac{a_{\rm drill}''}{a_{\rm drill}}+\frac{b_{\rm drill}''}{b_{\rm drill}}+\frac{a_{\rm drill}'b_{\rm drill}'}{a_{\rm drill}b_{\rm drill}}\right|\le c\frac{1}{R^2}.
    \]
    }
    \item{We have $a_{\rm drill}b_{\rm drill}\le \sinh(R)\cosh(R)e^{2r}$.}
\end{enumerate}
\end{lem}

ref_dict.lem:functionfill:
\begin{lem}
\label{lem:functionfill}
There exists a constant $c>0$ such that the following holds. For every $\ell_1>2\pi,\ell_2>0$ there exist functions $a_{\rm fill},b_{\rm fill}:\mb{R}\to\mb{R}$ that satisfy the following properties. Let $R=\log(\ell_1/\pi)$ and $\kappa=2\pi\ell_2/\ell_1$.
\begin{enumerate}
    \item{$a_{\rm fill},b_{\rm fill}>0$.}
    \item{$a_{\rm fill}(r)=2\pi\sinh(r+R),b(r+R)=\kappa\cosh(r+R)$ on $(-R,-2\delta)$.}
    \item{$a_{\rm fill}(r)=\ell_1e^r,b(r)=\ell_2 e^r$ on $(-\delta,0)$.}
    \item{We have
    \[
    \left|\frac{a_{\rm fill}''}{a_{\rm fill}}+\frac{b_{\rm fill}''}{b_{\rm fill}}+\frac{a_{\rm fill}'b_{\rm fill}'}{a_{\rm fill}b_{\rm fill}}-3\right|\le c\frac{\pi^4}{\ell_1^4}.
    \]
    }
    \item{We have 
    \[
    a_{\rm fill}b_{\rm fill}\le\ell_1\ell_2e^{2r}.
    \]
    }
\end{enumerate}
\end{lem}

