\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage{hyperref}
\usepackage{tikz}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\newtheorem{example}[theorem]{Example}
\newtheorem{question}[theorem]{Question}
\title[Crossing Numbers of Knots on Closed Surfaces]
{Crossing Numbers of Knots on Closed Surfaces}
\author{Makoto Ozawa}
\address{Department of Natural Sciences, Faculty of Arts and Sciences, Komazawa University, 1-23-1 Komazawa, Setagaya-ku, Tokyo, 154-8525, Japan}
\email{w3c@komazawa-u.ac.jp}
\date{\today}
\dedicatory{Dedicated to Professor Kanji Morimoto on the occasion of his retirement.}
\keywords{knot, surface crossing number, tunnel number, Heegaard deficiency, Heegaard splitting, surface bridge number, surface ascending number}
\begin{document}
\begin{abstract}
Let $c(K;F)$ denote the surface crossing number of a knot $K$ with respect
to a closed surface $F \subset S^{3}$. We establish the lower bound
\[
c(K;F) \ge 2\bigl(t(K)-\delta(F)\bigr)+1,
\]
where $t(K)$ is the tunnel number of $K$ and $\delta(F)$ is the Heegaard
deficiency of $F$. In particular, for any fixed closed surface $F$, the
surface crossing number $c(K;F)$ is unbounded over all knots $K$.
Furthermore, we construct a family of knots $K_m$ demonstrating that $c(K_m;F) = \Theta(t(K_m))$, which shows that this lower bound is asymptotically sharp.
\end{abstract}
\maketitle

\subsection{Main Results}
The objective of this paper is to establish a quantitative relationship between a knot's three-dimensional complexity, measured via its tunnel number, and its diagrammatic complexity on an arbitrary fixed closed surface.

The proof relies on a chain of inequalities relating the surface crossing number $c(K;F)$, the surface ascending number $a(K;F)$, and the surface bridge number $b(K;F)$:
$$\frac{c(K;F)-1}{2} \ge a(K;F) \ge b(K;F)-1 \ge t(K)-\delta(F).$$
This sequence demonstrates that the geometric obstruction to simplifying a knot diagram is bounded below by a combination of the knot exterior's complexity, $t(K)$, and the ambient surface's Heegaard deficiency, $\delta(F)$. Unlike the classical planar crossing number, $c(K;F)$ directly reflects the Heegaard-theoretic complexity of the knot.

Furthermore, we prove that the linear lower bound in Theorem \ref{thm:main_intro} is asymptotically optimal. For iterated connected sums $K_m$ of a prime knot (such as the trefoil), we obtain the linear growth estimate:
$$c(K_m;F) \ge 2m - 2\delta(F) + 1.$$
Pairing this with a general upper bound derived from the subadditivity of the planar crossing number yields $c(K_m;F) = \Theta(t(K_m))$. This confirms that no general lower bound of higher order exists, and that the surface crossing number grows linearly with respect to the tunnel number.

\begin{theorem}[Fundamental inequality]\label{thm:fundamental}
Let $F\subset S^{3}$ be a closed separating surface, and let $K\subset S^{3}$ be a knot. Then
\[
c(K;F) \ge 2\bigl(t(K)-\delta(F)\bigr)+1.
\]
\end{theorem}

Applying the fundamental inequality to $K_m$ yields:
\begin{proposition}
For every closed surface $F\subset S^{3}$,
\[
c(K_m;F) \ge 2\bigl(m-\delta(F)\bigr)+1 \to \infty \quad \text{as } m \to \infty.
\]
\end{proposition}

\section{Proof of the Main Inequality}
In this section, we prove Theorem \ref{thm:fundamental} by establishing the chain
$$\frac{c(K;F)-1}{2} \ge a(K;F) \ge b(K;F)-1 \ge t(K)-\delta(F).$$
Throughout the proof, let $F\subset S^{3}$ be a closed separating surface with decomposition
$S^{3}=M_{1}\cup_{F}M_{2}$.

\subsection{Generalization to spatial graphs}
The framework extends to spatial graphs. A spatial graph $G$ is a 1-dimensional CW complex embedded in $S^{3}$. The key arguments rely on the 1-dimensionality of the object: in the proof of Lemma \ref{lem:amalgamation}, a general position argument shows that the 2-dimensional attaching disks of the 1-handles can be made disjoint from $G$. The tunnel number $t(G)$, bridge position, and ascending number extend to this setting, and one expects a lower bound of the form
\[
c(G;F) \ge 2\bigl(t(G)-\delta(F)\bigr) + C_G,
\]
where $C_G$ is a constant depending on the combinatorial structure of $G$ (such as its Euler characteristic or vertex degrees).

\begin{theorem}[Fundamental inequality]\label{thm:main_intro}
Let $F\subset S^3$ be a closed surface. Then every knot $K\subset S^3$ satisfies:
\[
c(K;F) \ge 2\bigl(t(K)-\delta(F)\bigr)+1,
\]
where $t(K)$ is the tunnel number of $K$, and $\delta(F)=g(M_1)+g(M_2)-g(F)$ is the Heegaard deficiency of $F$.
\end{theorem}

